create or replace function public.enforce_live_listing_price_on_new_order() returns trigger language plpgsql security definer set search_path=public as $$ declare item jsonb; lid uuid; live_price numeric; qty integer; new_items jsonb:='[]'::jsonb; total numeric:=0; begin if tg_op<>'INSERT' then return new; end if; if new.payment_status not in ('pending','awaiting_payment','unpaid') then return new; end if; if jsonb_typeof(coalesce(new.items,'[]'::jsonb))<>'array' then return new; end if; for item in select value from jsonb_array_elements(new.items) loop lid:=null; if (item->>'listing_id') is not null then begin lid:=(item->>'listing_id')::uuid; exception when others then lid:=null; end; end if; if lid is not null then select coalesce(price_amount,0) into live_price from public.listings where id=lid and is_published=true and moderation_status='approved' for share; if live_price<=0 then raise exception 'Current admin property price is unavailable for listing %',lid; end if; qty:=greatest(1,coalesce((item->>'quantity')::integer,1)); item:=jsonb_set(item,'{unit_price}',to_jsonb(live_price),true); item:=jsonb_set(item,'{price}',to_jsonb(live_price),true); item:=jsonb_set(item,'{price_source}','"admin_listing_price_live"'::jsonb,true); item:=jsonb_set(item,'{price_snapshot_at}',to_jsonb(now()),true); end if; new_items:=new_items||jsonb_build_array(item); total:=total+(case when lid is not null then live_price else coalesce((item->>'unit_price')::numeric,(item->>'price')::numeric,0) end)*greatest(1,coalesce((item->>'quantity')::integer,1)); end loop; if total>0 then new.items:=new_items; new.total_amount:=total; end if; return new; end; $$; drop trigger if exists trg_enforce_live_listing_price on public.orders; create trigger trg_enforce_live_listing_price before insert on public.orders for each row execute function public.enforce_live_listing_price_on_new_order();
